/*
	Hypnosis #genuary19 #genuary #genuary2519
	Op Art.
	https://openprocessing.org/sketch/2515654
	#generativeart #creativecoding #p5js
*/

let NUM = 10;
let BG = "#282030";
let gradShader, fgClrs, bgClrs;

function setup() {
  createCanvas(S= min(innerWidth, innerHeight), S);
	describe("animated op art animated vertical lines overlaped by shrinking circles at each intersection switching color black & white with gradient overlay");
	pixelDensity(1);
  frameRate(30);
  // noFill();
  // stroke("rgba(0,0,0,0.1)");
	noStroke();
	fill("white")

	gradShader = createFilterShader(gradShaderSrc);
	fgClrs = get4Colors();
	bgClrs = get4Colors();

  loop();
}

function draw() {
	blendMode(BLEND);
	background(BG);

	// horizontal "lines"
	blendMode(DIFFERENCE);
	const dy = ~~(height / NUM);
	for (let y = (2*frameCount) % (2*dy) - 8*dy; y < height + 8*dy; y += 2*dy) {
		triangle(
			-width*0.5, height/2,
			width/2, y,
			width/2, y + dy,
		)
		triangle(
			width*1.5, height/2,
			width/2, y + dy,
			width/2, y + 2 * dy,
		)
	}

	// left right circles
	const numC = 6;
	for (let i = 0; i <= numC; i++) {	
		const dia = S - i*S/6 - ((frameCount) % (S/6));
		// left right
		circle(0, height/2, dia);
		circle(width, height/2, dia);

		if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {			
			// top bottom
			circle(width/2, 0, dia);
			circle(width/2, height, dia);

			// corners tl tr br bl
			circle(0, 0, dia);
			circle(width, 0, dia);
			circle(width, height, dia);
			circle(0, height, dia);
		}
		// middle
		circle(width/2, height/2, dia);
	}

	// top down traingles
	const numT = 5;
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		for (let i = 1; i <= numT; i++) {	
			const len = i*S/8;
			triangle(
				width/2-len/2, 0,
				width/2+len/2, 0,
				width/2, len/2
			);
			triangle(
				width/2-len/2, height,
				width/2+len/2, height,
				width/2, height-len/2
			);
		} // triangles
	}

	// shader
	gradShader.setUniform('clrFg1', colorToArr(fgClrs[0])); // colorToArr(color(random(["cyan", "darkorange", "navy", "pink"])))); // [0.75, 0.25, 0.55, 1.0]
	gradShader.setUniform('clrFg2', colorToArr(fgClrs[1])); // colorToArr(color(random(["cyan", "darkorange", "navy", "pink"])))); // [0.75, 0.25, 0.55, 1.0]
	gradShader.setUniform('clrFg3', colorToArr(fgClrs[2])); // colorToArr(color(random(["cyan", "darkorange", "navy", "pink"])))); // [0.75, 0.25, 0.55, 1.0]
	gradShader.setUniform('clrFg4', colorToArr(fgClrs[3])); // colorToArr(color(random(["cyan", "darkorange", "navy", "pink"])))); // [0.75, 0.25, 0.55, 1.0]

	gradShader.setUniform('clrBg1', colorToArr(bgClrs[0])); // colorToArr(color(random(["cyan", "darkorange", "navy", "pink"])))); // [0.75, 0.25, 0.55, 1.0]
	gradShader.setUniform('clrBg2', colorToArr(bgClrs[1])); // colorToArr(color(random(["cyan", "darkorange", "navy", "pink"])))); // [0.75, 0.25, 0.55, 1.0]
	gradShader.setUniform('clrBg3', colorToArr(bgClrs[2])); // colorToArr(color(random(["cyan", "darkorange", "navy", "pink"])))); // [0.75, 0.25, 0.55, 1.0]
	gradShader.setUniform('clrBg4', colorToArr(bgClrs[3])); // colorToArr(color(random(["cyan", "darkorange", "navy", "pink"])))); // [0.75, 0.25, 0.55, 1.0]

	gradShader.setUniform('gamma', 0.5);
	filter(gradShader);

	drawMsg("op art (epi) #genuary2519")
}

function colorToArr(clr) {
	return [
		red(window.color(clr))/255,
		green(window.color(clr))/255,
		blue(window.color(clr))/255,
		alpha(window.color(clr))/255
	]
}

function get4Colors(n = 4) { // tl, tr, br, bl
	push();
	colorMode(HSB, 1);
	const arr = [];
	const hueStart = random(1);
	const hueDltX = random(0.1, 0.25);
	const hueDltY = random(0.1, 0.25);

	const satStart = random(1);
	const satDltX = random(0.1, 0.25);
	const satDltY = random(0.1, 0.25);

	const brStart = random(1);
	const brDltX = random(0.1, 0.25);
	const brDltY = random(0.1, 0.25);

	arr.push(color(hueStart, satStart, brStart));
	arr.push(color((hueStart+hueDltX)%1, (satStart+satDltX)%1, (brStart+brDltX)%1));
	arr.push(color((hueStart+hueDltX+hueDltY)%1, (satStart+satDltX+satDltY)%1, (brStart+brDltX+brDltY)%1));
	arr.push(color((hueStart+hueDltY)%1, (satStart+satDltY)%1, (brStart+brDltY)%1));

	pop();

	//console.log(arr);
	return arr;
}

function drawMsg(msg) {
	push();
	blendMode(BLEND);

	fill("black")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 1, 1)

	fill("white")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 0, 0)

	pop();
}

function doubleClicked() {
	if (mouseButton !== RIGHT) setup();
}
